    for (i = iA; i <= iB; i++) { if (i !== 0) txt(tick(i * mt.major), toX(i * mt.major), xlY, col.muted, "center"); }
    iA = Math.ceil(ymin / mt.major); iB = Math.floor(ymax / mt.major);
    for (i = iA; i <= iB; i++) { if (i !== 0) txt(tick(i * mt.major), ylX, toY(i * mt.major) + 4, col.muted, "right"); }
    if (ox >= 0 && ox <= W && oy >= 0 && oy <= H) txt("0", ylX, xlY, col.muted, "right");

